  function vehicle(c){const sorted=[...c.events].sort(newest),year=today().slice(0,4);return `${back('home','Koti')}<div class="vehicle-hero">${vehicleImage(c)}<h2 class="app-heading">${escape(carName(c))}</h2><p>${c.nick?escape(c.name)+' · ':''}${[c.plate?escape(c.plate):'',c.year,typeOf(c),colorName(c.color),c.fuel?escape(c.fuel):'',c.engine?escape(c.engine):''].filter(Boolean).join(' · ')}</p><div class="photo-actions"><label class="photo-button">＋ ${c.photo?'Lisää kuvia':'Lisää omia kuvia'}<input type="file" accept="image/*" multiple data-car-photos="${c.id}" class="sr-only"></label>${c.photo?`<button type="button" class="photo-button plain" data-photo-remove="${c.id}">Poista pääkuva</button>`:''}<a class="photo-button" href="#caredit/${c.id}">Muokkaa tietoja</a></div>${carGallery(c)}</div>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}${notice&&/lisätty talliin\.$/.test(notice)?addedNext(c):''}<div class="app-stats"><div><strong>${number(c.km)} <small>${ku(c)}</small></strong><span>${hourly(c)?'Käyttötunnit':'Mittarilukema'}</span></div><div><strong>${c.events.length}</strong><span>Merkintää</span></div></div><div class="cost-line"><span>Kirjatut kulut yhteensä</span><strong>${number(costOf(c.events))} €</strong><small>Vuonna ${year}: ${number(costOf(c.events.filter(e=>e.date.startsWith(year))))} €</small>${(f=>f?`<small class="fuel-cost">${unitOf(c)==='kWh'?'Latauskulut':'Polttoaine'} ${year}: ${number(f)} €</small>`:'')((c.fuels||[]).filter(f=>f.date.startsWith(year)&&f.cost!==null).reduce((m,f)=>m+f.cost,0))}</div>${notesCard(c)}${fuelCard(c)}<a class="app-button" href="#add/${c.id}">＋ Lisää merkintä</a>${upcoming(c)}${tipsCard(c)}${kmChart(c)}<div class="history-heading"><h3>Huoltohistoria</h3><a href="#report/${c.id}">Raportti →</a></div>${sorted.length?timeline(c,sorted):'<p class="app-empty">Ei vielä tapahtumia. Lisää ensimmäinen merkintä yllä olevasta painikkeesta.</p>'}<p class="app-note">${c.sample?'Esimerkkiauto: kuvitteellinen historia, rekisteritunnus ja hinnat. ':''}${c.photo?'Kuva on omasi ja pysyy tässä laitteessa.':(isCar(c)?'Automalli on tyylitelty kuvitus valitsemastasi korimallista ja väristä. Voit vaihtaa tilalle oman kuvan.':'Kuva on piirretty kuvitus valitsemastasi tyypistä ja väristä. Voit vaihtaa tilalle oman kuvan.')}</p><button class="app-back danger-link" type="button" data-remove="${c.id}">Poista ajoneuvo</button>`;}
