  function me(){return `${back('menu','Valikko')}<h2 class="app-heading">Varmuuskopio ja tiedot</h2>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}<div class="me-data"><h3>Varmuuskopio</h3><p>Tallenna autot, merkinnät ja tankkaukset tiedostoon. Palauttamalla tiedoston saat ne takaisin, myös uudessa puhelimessa. Palautus yhdistää tiedot: sama auto päivittyy ja uudet lisätään.</p><div class="backup-actions"><button class="app-button" type="button" data-backup>Tallenna varmuuskopio</button><label class="app-button secondary">Palauta varmuuskopio<input type="file" accept="application/json,.json" class="sr-only" data-restore></label></div><p class="app-fineprint">${stamp(backupKey)?'Viimeisin varmuuskopio: '+new Intl.DateTimeFormat('fi-FI').format(new Date(stamp(backupKey))):'Varmuuskopiota ei ole vielä otettu tällä laitteella.'}</p></div>${window.AjouraSync&&window.AjouraSync.enabled?window.AjouraSync.meCard():`<div class="me-data"><h3>Tili <small class="soon-tag">tulossa</small></h3><p>Myöhemmin kirjautumalla autosi ja merkintäsi tallentuvat turvallisesti ja siirtyvät mukanasi uuteen puhelimeen. Siihen asti käytä varmuuskopiota.</p><button class="app-button secondary" type="button" data-login>Kirjaudu sisään <small class="soon-tag">tulossa</small></button>${loginNote?'<p class="login-note" role="status"><strong>Kirjautuminen on tulossa.</strong> Sitä ennen tiedot pysyvät tässä laitteessa.</p>':''}</div>`}<div class="me-data"><h3>Tietosi</h3><p>Autot ja merkinnät tallentuvat vain tähän laitteeseen. Niitä ei lähetetä palvelimelle.${installed?'':' Asenna AJOURA puhelimen kotivalikkoon: selain voi muuten poistaa tiedot, jos sivulla ei käydä pitkään aikaan. Ota myös varmuuskopio.'}</p><button class="app-button secondary danger" type="button" data-reset>Poista kaikki tiedot</button></div>`;}
  function settings(){return `${back('menu','Valikko')}<h2 class="app-heading">Asetukset</h2>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}<form class="app-form" id="me-form" novalidate><fieldset class="interval-set"><legend>Huoltomuistutuksen väli</legend><div class="form-row"><label>Kuukautta<input name="months" type="number" required min="1" max="36" step="1" inputmode="numeric" value="${profile.months}"></label><label>Kilometriä<input name="km" type="number" enterkeyhint="next" required min="1000" max="60000" step="500" inputmode="numeric" value="${profile.km}"></label></div><p class="field-help">Tarkista oikea väli autosi huolto-ohjelmasta. Muistutus tulee sen mukaan, kumpi täyttyy ensin.</p></fieldset><p class="error-note" id="form-error" role="alert"></p><button class="app-button" type="submit">Tallenna asetukset</button></form><div class="me-data"><h3>Kieli ja ulkoasu</h3>${prefsBar()}</div>`;}
  function feedbackPage(){return `${back('menu','Valikko')}<h2 class="app-heading">Anna palautetta</h2><p class="app-subtitle">Testaatko AJOURAa? Kerro, mikä toimi ja mikä ei.</p><div class="feedback-page">${feedbackForm()}</div>`;}
  // Valikko tab: rows like a phone's settings list. Each opens a sub-page with a back link, because the installed
