  function menu(){return `${top()}<h2 class="app-heading">Valikko</h2>${notice?`<p class="success-note" role="status">${escape(notice)}</p>`:''}<div class="menu-group">${menuRow('#settings','gear','Asetukset','Huoltoväli, kieli ja ulkoasu')}${menuRow('#me','save','Varmuuskopio ja tiedot','Tallenna, palauta tai poista tiedot')}</div><h3 class="menu-h">Ohjeet ja tuki</h3><div class="menu-group">${(s=>menuRow('#tips',s.icon,'Kausi- ja huoltovinkit',`<span>Nyt:</span> <span>${s.chip.fi}</span>`))(seasonNow())}${menuRow('#help','help','Ohjeet ja kysymykset','Yleisimmät kysymykset ja haku')}${menuRow('data-tutorial','play','Käyttöönoton opas','Lyhyt esittely sovelluksesta')}${menuRow('#feedback','chat','Anna palautetta','Kerro, mikä toimi ja mikä ei')}${menuRow('data-share-app','share','Suosittele AJOURAa','Jaa linkki kaverille')}</div><h3 class="menu-h">Tietoa</h3><div class="menu-group">${menuRow('tietosuoja.html','inspection','Tietosuoja','Mitä tietoja sovellus käsittelee')}</div><p class="app-fineprint menu-version">AJOURA ${appVersion}</p>`;}
  // Raportit tab: every vehicle's report in one place. Comparing vehicles comes next (pala B).
  // Raportit 0.27 (Niklas 25.10.2026): costs for a chosen period, vehicles and cost types, as key figures and a bar per vehicle.
