    const ev=cars.some(c=>c.fuel==='Sähkö'||c.fuel==='Lataushybridi'),kn=k=>k==='fuel'&&ev?'Polttoaine ja lataus':costKinds.find(([x])=>x===k)[1];
    const pick=(s,ks)=>{const r={};let t=0;for(const k of ks){r[k]=s[k];t+=s[k];}return [r,t];};
