    // does not skew it.
    const pSum=rows.reduce((m,r)=>m+r.pt,0),both=rows.filter(r=>!hourly(r.c)&&r.d>=100&&r.pd>=100),sumOf=f=>both.reduce((m,r)=>m+f(r),0);
