      doc.text(L+112,y+4.4,r.d>0?`${number(r.d)} ${r.u}`:'–',{size:9.5,align:'right'});
      doc.text(L+140,y+4.4,r.per!==null?`${dec2(r.per)} €/${r.u}`:'–',{size:9.5,align:'right'});
